#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# This one takes a Linux server from a bare checkout to a running service:
# prerequisites, the projects root, the login password file, the provider
# profiles, a systemd unit, the firewall, and a /healthz that answers.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9

# Everything captured here lands in one file this wizard owns, and the unit
# reads a root-owned copy of it. The split is deliberate: the staged file stays
# user-owned so a re-run can read its own answers back (`_existing`), and the
# copy under /etc is the one systemd reads — 0600 and root-owned, which is
# where a service's environment belongs (README §"Linux server").
STATE_DIR="$HOME/.config/clodeck"
STAGE_ENV="$STATE_DIR/clodeck.env"
STAGE_UNIT="$STATE_DIR/clodeck.service"
PASSWORD_FILE="$STATE_DIR/password"
ENV_FILE="$STAGE_ENV"

# The checkout this wizard lives in, whatever directory it was invoked from.
cd "$(dirname "${BASH_SOURCE[0]}")/.."
REPO_ROOT="$PWD"

mkdir -p "$STATE_DIR"
chmod 700 "$STATE_DIR"

banner "Clodeck on a server"

# ── 1. The checkout and the toolchain ─────────────────────────────────────
stage "The checkout and the toolchain"
say "This wizard deploys the copy of clodeck it lives in: $REPO_ROOT"

if [[ "$(uname -s)" != "Linux" ]]; then
  warn "this wizard writes a systemd unit and opens a port — it is for a Linux server"
  exit 1
fi

if [[ ! -f package.json ]] || ! grep -q '"name": "clodeck"' package.json; then
  warn "no clodeck package.json in $REPO_ROOT — run this from a clodeck checkout"
  exit 1
fi
say "the checkout looks like clodeck ✓"

# The terminal drawer is a real shell with the server's privileges, so the
# server must not be root: systemd would hand it a root prompt.
if [[ "$(id -u)" -eq 0 ]]; then
  warn "run this as the user the server should run as, never as root — the"
  warn "terminal drawer would be a root shell. Try:"
  note "    sudo -u <user> bash scripts/deploy-clodeck.sh"
  exit 1
fi

SERVICE_USER=$(id -un)
say "the service will run as $SERVICE_USER ✓"

# /etc, systemctl and the firewall are stages 7 and 8, so sudo is asked for
# now, once, rather than stalling in the middle of a stage later.
if ! command -v sudo >/dev/null 2>&1; then
  warn "sudo is not here, and stages 7 and 8 need it for /etc, systemd and the firewall"
  exit 1
fi
if sudo -v; then
  say "sudo is available ✓"
else
  warn "sudo refused — this wizard cannot install the service without it"
  exit 1
fi

# git and curl are needed whatever happens next; the compiler is what `npm ci`
# needs on Linux — node-pty has no prebuild there — so python3, make and g++ are
# only asked for when there is no node_modules to skip that install.
need=()
for tool in git curl; do
  command -v "$tool" >/dev/null 2>&1 || need+=("$tool")
done
if [[ ! -d node_modules ]]; then
  for tool in python3 make g++; do
    command -v "$tool" >/dev/null 2>&1 || need+=("$tool")
  done
fi

node_ok=no
node_state="not installed"
if command -v node >/dev/null 2>&1; then
  node_version=$(node --version)
  node_major=${node_version#v}; node_major=${node_major%%.*}
  node_rest=${node_version#v};  node_rest=${node_rest#*.}
  node_minor=${node_rest%%.*}
  node_state="$node_version"
  if [[ "$node_major" =~ ^[0-9]+$ && "$node_minor" =~ ^[0-9]+$ ]] \
    && (( node_major > 22 || (node_major == 22 && node_minor >= 12) )); then
    node_ok=yes
    say "node $node_version ✓"
  else
    node_state="$node_version (older than the 22.12 this repo needs)"
  fi
fi

if (( ${#need[@]} )) || [[ "$node_ok" == "no" ]]; then
  if (( ${#need[@]} )); then
    say "missing: ${need[*]}"
  fi
  [[ "$node_ok" == "no" ]] && say "node: $node_state"

  if ! command -v apt-get >/dev/null 2>&1; then
    warn "apt-get is not here, so this wizard cannot install them. Install Node"
    warn "22.12+, git, python3, make and g++ with your package manager, then re-run."
    exit 1
  fi

  if ! confirm "Install them now with apt (sudo)?"; then
    warn "skipped — nothing can be installed or built without them"
    exit 1
  fi

  # Both of these reach the network, so both are checked: a bare failure here
  # under `set -e` would end the run with apt's own message and no next step.
  if [[ "$node_ok" == "no" ]]; then
    say "adding the NodeSource repository for Node 22…"
    if ! curl -fsSL https://deb.nodesource.com/setup_22.x | sudo -E bash -; then
      warn "could not fetch the NodeSource setup script — check the network and re-run"
      exit 1
    fi
    if ! sudo apt-get install -y nodejs; then
      warn "apt could not install nodejs — read its output and re-run"
      exit 1
    fi
  fi
  if (( ${#need[@]} )); then
    if ! sudo apt-get install -y "${need[@]}"; then
      warn "apt could not install ${need[*]} — read its output and re-run"
      exit 1
    fi
  fi

  if ! command -v node >/dev/null 2>&1; then
    warn "node is still not on PATH — install it and re-run"
    exit 1
  fi
  say "toolchain in place: node $(node --version) ✓"
fi

if [[ -d node_modules ]]; then
  say "dependencies are installed ✓"
elif confirm "node_modules is missing — run npm ci now (it compiles node-pty; a minute or two)?"; then
  if npm ci; then say "installed ✓"; else warn "npm ci failed — fix it and re-run"; exit 1; fi
else
  warn "skipped: there is nothing to build or run without it"
  SKIPPED+=("npm ci")
fi

pause

# ── 2. The projects root ──────────────────────────────────────────────────
stage "The projects root"
say "Every immediate child directory of this path is one project. clodeck keeps"
say "no database, so the folders in here are the whole registry. One level deeper"
say "is not listed, and neither is a plain file or a dot-directory."

ask PROJECTS_ROOT "Projects root (Enter for ~/clodeck-projects):"
PROJECTS_ROOT="${PROJECTS_ROOT:-$HOME/clodeck-projects}"

if [[ -d "$PROJECTS_ROOT" ]]; then
  say "found it ✓"
elif confirm "$PROJECTS_ROOT does not exist — create it?"; then
  mkdir -p "$PROJECTS_ROOT"
  say "created it ✓"
else
  warn "left missing: the sidebar stays empty until it exists"
  SKIPPED+=("create the projects root $PROJECTS_ROOT")
fi

if [[ -d "$PROJECTS_ROOT" && ! -w "$PROJECTS_ROOT" ]]; then
  warn "$PROJECTS_ROOT is not writable by $SERVICE_USER, so creating a project,"
  warn "uploading a file and letting the agent edit one would all fail"
  SKIPPED+=("make $PROJECTS_ROOT writable by $SERVICE_USER")
fi

if [[ -d "$PROJECTS_ROOT" && -z "$(ls -A "$PROJECTS_ROOT" 2>/dev/null || true)" ]]; then
  if confirm "It is empty — create a sample project hello/ inside it?"; then
    mkdir -p "$PROJECTS_ROOT/hello"
    say "created hello/ ✓"
  fi
fi

write_env PROJECTS_ROOT "$PROJECTS_ROOT"
note "clodeck.config.json can hold projectsRoot instead; nothing else goes in it."

pause

# ── 3. The login password ─────────────────────────────────────────────────
stage "The login password"
say "One account, one password, asked for before anything else is served. It goes"
say "into a file only $SERVICE_USER can read, and the service reads it from there."
note ""
say "It deliberately does not go in the environment file: `ps` and `docker"
say "inspect` show an environment, and a password should not be in one."

if [[ -s "$PASSWORD_FILE" ]]; then
  say "a password file already exists: $PASSWORD_FILE"
  note "Enter at the prompt keeps it; type a new one to replace it."
fi

UI_PASSWORD=""
if confirm "Generate a long one and show it?"; then
  if command -v openssl >/dev/null 2>&1; then
    UI_PASSWORD=$(openssl rand -base64 24 || true)
  else
    UI_PASSWORD=$(head -c 24 /dev/urandom | base64 || true)
  fi
  if [[ -n "$UI_PASSWORD" ]]; then
    printf '\n  %syour password:%s %s%s%s\n\n' "$BOLD" "$RESET" "$GREEN" "$UI_PASSWORD" "$RESET"
    note "write it down now — the file below is the only other copy."
  else
    warn "could not generate one: neither openssl nor /dev/urandom + base64 worked"
    SKIPPED+=("generate a password — re-run and type one at the prompt instead")
  fi
else
  ask_secret UI_PASSWORD "Choose the login password:"
fi

if [[ -n "$UI_PASSWORD" ]]; then
  (umask 077; printf '%s' "$UI_PASSWORD" > "$PASSWORD_FILE")
  say "wrote it to $PASSWORD_FILE ✓ (mode 600, $SERVICE_USER's)"
elif [[ -s "$PASSWORD_FILE" ]]; then
  say "keeping the password already in $PASSWORD_FILE ✓"
else
  warn "no password anywhere: the server boots fail-closed and refuses every login"
  SKIPPED+=("a login password")
fi

write_env UI_PASSWORD_FILE "$PASSWORD_FILE"

# `UI_PASSWORD` wins over `UI_PASSWORD_FILE`, so a leftover one would shadow the
# file without saying so. There is never a reason to keep it here.
if [[ -n "$(_existing UI_PASSWORD || true)" ]]; then
  write_env UI_PASSWORD ""
  note "blanked a UI_PASSWORD line that would have shadowed the file."
fi

note "Hashed once at boot: changing it means a restart, and a restart drops every session."

pause

# ── 4. The server's own environment ───────────────────────────────────────
# The questions from here to stage 6 are the ones scripts/setup-clodeck.sh asks,
# in its own words: one vocabulary for the endpoint and the tiers, so the two
# wizards cannot drift apart in meaning.
stage "The endpoint every run starts on"
say "This is the reserved 'default' profile: the server's own environment."
say "Sessions run on it unless one picks a profile from stages 5 or 6."
note ""
say "clodeck speaks the Anthropic Messages API and nothing else. Anthropic's own"
say "API is one; DeepSeek's /anthropic surface is another; a vendor with neither"
say "reaches you through a translation proxy you run yourself."
note ""
say "The pages below are DeepSeek's, as the README's example. On another vendor,"
say "ignore them and use that vendor's dashboard."

step "Sign in, find the API keys section, and create a key."
open_url "https://platform.deepseek.com/"
step "Model names are on the vendor's own docs page:"
open_url "https://api-docs.deepseek.com/guides/anthropic_api"

ask ANTHROPIC_BASE_URL "Base URL (blank = Anthropic's own api.anthropic.com):"

# The credential's variable name follows the endpoint, and asking against the
# real name is what makes a re-run remember it: Anthropic's own API is read from
# ANTHROPIC_API_KEY, everything else from the ANTHROPIC_AUTH_TOKEN that provider
# profiles inherit. The other name is blanked, so switching vendors cannot leave
# one vendor's key sitting beside another vendor's endpoint.
if [[ -n "$ANTHROPIC_BASE_URL" ]]; then
  credential_var=ANTHROPIC_AUTH_TOKEN
  stale_var=ANTHROPIC_API_KEY
else
  credential_var=ANTHROPIC_API_KEY
  stale_var=ANTHROPIC_AUTH_TOKEN
fi

ask_secret "$credential_var" "The API key / token for it:"
credential="${!credential_var}"

if [[ -n "$credential" ]]; then
  write_env "$credential_var" "$credential"
else
  warn "no credential: login, terminal and files work, and the chat answers nothing"
  SKIPPED+=("a provider credential")
fi

if [[ -n "$ANTHROPIC_BASE_URL" ]]; then
  write_env ANTHROPIC_BASE_URL "$ANTHROPIC_BASE_URL"
fi

# Only a name that actually holds something is blanked: on a first run the
# other name is not there at all, and an empty line is not worth writing.
if [[ -n "$(_existing "$stale_var" || true)" ]]; then
  write_env "$stale_var" ""
fi

ask ANTHROPIC_MODEL "Default model (blank = let the endpoint choose):"
if [[ -n "$ANTHROPIC_MODEL" ]]; then
  write_env ANTHROPIC_MODEL "$ANTHROPIC_MODEL"
else
  note "left to the endpoint: it answers with whatever model it defaults to."
fi

note ""
note "This file is 0600 and root-owned under /etc, and no browser is ever shown a"
note "part of it. A key written into a project's .claude/settings.json is a key"
note "the agent it pays for can open — that is why credentials belong here."

pause

# ── 5. Tiers ──────────────────────────────────────────────────────────────
stage "Tiers: one endpoint, several models"
say "A tier is a profile that declares a model and nothing else — the endpoint"
say "and the credential come from the server's environment you just set. This is"
say "the cheap-model-for-grunt-work / strong-model-for-design switch."
note ""
note "Name them for what they are for: flash, pro, cheap, big…"
note "The picker shows a name upper-cased with - folded to _."

while :; do
  ask TIER_NAME "Profile name (blank to finish):"
  if [[ -z "$TIER_NAME" ]]; then break; fi

  # Whitespace first: an environment variable's name cannot hold any, and the
  # server's own normalization would otherwise carry a stray space into a key.
  tier=$(printf '%s' "$TIER_NAME" | tr -d '[:space:]' | tr '[:lower:]' '[:upper:]' | tr '-' '_')
  if [[ "$tier" == "DEFAULT" ]]; then
    warn "\"default\" is reserved for the server's own environment — another name?"
    continue
  fi

  ask TIER_MODEL "Model for $tier:"
  if [[ -z "$TIER_MODEL" ]]; then
    warn "no model given — skipping $tier"
    continue
  fi

  write_env "CLODECK_PROVIDER_${tier}_MODEL" "$TIER_MODEL"
done

note "Profiles are read once, at boot: adding one later is a restart."

pause

# ── 6. A second provider ──────────────────────────────────────────────────
stage "A second provider (optional)"
say "A profile may also carry its own endpoint and credential — a second vendor"
say "beside the first. Endpoint and credential travel together; the model is the"
say "only part a session can change."

if confirm "Add one?"; then
  ask PROVIDER_NAME "Profile name (e.g. gateway):"
  provider=$(printf '%s' "$PROVIDER_NAME" | tr -d '[:space:]' | tr '[:lower:]' '[:upper:]' | tr '-' '_')

  if [[ -z "$provider" || "$provider" == "DEFAULT" ]]; then
    warn "a name is needed, and \"default\" is taken — nothing written"
    SKIPPED+=("the second provider's profile name")
  else
    ask PROVIDER_BASE_URL "Its base URL (must speak the Anthropic Messages API):"
    provider_credential_var="CLODECK_PROVIDER_${provider}_AUTH_TOKEN"
    ask_secret "$provider_credential_var" "Its API key / token:"
    provider_credential="${!provider_credential_var}"
    ask PROVIDER_MODEL "Its model:"

    if [[ -z "$PROVIDER_BASE_URL" || -z "$provider_credential" || -z "$PROVIDER_MODEL" ]]; then
      warn "all three are needed, or the profile is not one — nothing written"
      SKIPPED+=("the second provider's profile")
    else
      write_env "CLODECK_PROVIDER_${provider}_BASE_URL" "$PROVIDER_BASE_URL"
      write_env "$provider_credential_var" "$provider_credential"
      write_env "CLODECK_PROVIDER_${provider}_MODEL" "$PROVIDER_MODEL"
      note "A vendor with no Anthropic surface needs a translation proxy in front of it,"
      note "with this profile pointed at the proxy instead."
    fi
  fi
else
  note "skipped: re-run this wizard whenever you want to add one."
fi

pause

# ── 7. The service ────────────────────────────────────────────────────────
stage "The service"
say "The app becomes a systemd unit, so it survives your logout and a reboot."

ask PORT "Port (Enter for 3001):"
PORT="${PORT:-3001}"
write_env PORT "$PORT"

say ""
say "Now the origin a browser will type — scheme, address and port. It is the one"
say "fact nothing inside the process can work out, and it decides the session"
say "cookie's Secure flag, which is what makes a login stick."

# The first global address this machine reports, as the hint for the origin:
# guessing it wrong is a login that bounces, so it is shown rather than assumed.
detect_ip() {
  local ip=""
  # IPv4 only: `hostname -I` also lists IPv6, and a link-local fe80:: address is
  # not something a browser can be pointed at.
  if command -v hostname >/dev/null 2>&1; then
    ip=$( { hostname -I 2>/dev/null | tr ' ' '\n' \
      | grep -E '^[0-9]+(\.[0-9]+){3}$' | grep -vE '^127\.' | head -n1; } || true )
  fi
  if [[ -z "$ip" ]] && command -v ip >/dev/null 2>&1; then
    ip=$( { ip route get 1.1.1.1 2>/dev/null \
      | awk '{for(i=1;i<=NF;i++) if($i=="src") {print $(i+1); exit}}'; } || true )
  fi
  printf '%s' "$ip"
}

detected_ip=$(detect_ip)
if [[ -n "$detected_ip" ]]; then
  note "this machine answers on $detected_ip — so that would be http://$detected_ip:$PORT"
fi

ask CLODECK_PUBLIC_URL "Origin a browser types (blank = loopback only):"

if [[ -z "$CLODECK_PUBLIC_URL" ]]; then
  write_env HOST "127.0.0.1"
  warn "no origin declared: the server binds loopback and the cookie stays Secure."
  say "That is reachable through an SSH tunnel and nothing else:"
  note "    ssh -N -L $PORT:127.0.0.1:$PORT $SERVICE_USER@<this host>"
  note "    then open http://localhost:$PORT"
  note "A blank answer keeps an origin already saved from an earlier run — delete"
  note "that line from $STAGE_ENV to fall back to loopback."
  SKIPPED+=("declare CLODECK_PUBLIC_URL to reach it from a browser directly")
elif [[ "$CLODECK_PUBLIC_URL" == http://* ]]; then
  write_env HOST "0.0.0.0"
  write_env CLODECK_PUBLIC_URL "$CLODECK_PUBLIC_URL"
  warn "declared an http: origin, so the cookie is not Secure — which is what lets"
  warn "a bare origin hold a login, at a cost said twice in the README: the"
  warn "password, every chat message and every byte of terminal output cross the"
  warn "network in cleartext, readable by anyone on the path. The server warns at"
  warn "startup and the login screen says it where you type the password."
  say "It has to be exactly what the browser types: a different address, or a"
  say "missing port, is a login that bounces with no error (README §\"When the"
  say "origin is not declared\")."
elif [[ "$CLODECK_PUBLIC_URL" == https://* ]]; then
  write_env HOST "0.0.0.0"
  write_env CLODECK_PUBLIC_URL "$CLODECK_PUBLIC_URL"
  say "an https: origin keeps the cookie Secure ✓"
  note "if a proxy or Caddy terminates that TLS on this host, add"
  note "CLODECK_TRUSTED_PROXIES=127.0.0.1/8 above and re-run: without it every"
  note "login arrives from the proxy, so five failures from anyone lock out the one"
  note "user there is."
else
  warn "\"$CLODECK_PUBLIC_URL\" is not an http:// or https:// origin. Writing it"
  warn "anyway: the scheme is what the cookie flag is read from, and a typo here"
  warn "is a login that bounces rather than an error."
  write_env HOST "0.0.0.0"
  write_env CLODECK_PUBLIC_URL "$CLODECK_PUBLIC_URL"
fi

write_env WEB_ROOT "$REPO_ROOT/web/dist"

# systemd's EnvironmentFile reads a value literally: a space has to be quoted,
# and the library's write_env cannot know that. Cheaper to say so than to debug
# a path that arrives in two pieces.
if grep -qE '^[A-Z0-9_]+=[^[:space:]]*[[:space:]]' "$STAGE_ENV"; then
  warn "a value in $STAGE_ENV holds a space. systemd will split it unless it is"
  warn "quoted (KEY=\"a b\") — edit that line, then run stage 7 again."
fi

say ""
say "Building the three packages — the unit runs the built server, not a dev loop."
if npm run build; then
  say "built ✓"
else
  warn "the build failed — read the lines above, fix them, and re-run"
  exit 1
fi

NODE_BIN=$(command -v node)
UNIT=/etc/systemd/system/clodeck.service

cat > "$STAGE_UNIT" <<UNIT_FILE
[Unit]
Description=Clodeck
After=network.target

[Service]
Type=simple
User=$SERVICE_USER
WorkingDirectory=$REPO_ROOT/server
ExecStart=$NODE_BIN dist/main.js
EnvironmentFile=/etc/clodeck/clodeck.env
Restart=on-failure
RestartSec=3

[Install]
WantedBy=multi-user.target
UNIT_FILE

# WorkingDirectory is load-bearing twice over: dist/main.js resolves against it,
# and so does clodeck.config.json, if one is ever put there.
note ""
note "the unit runs: $NODE_BIN dist/main.js, as $SERVICE_USER, from $REPO_ROOT/server"
note "the staged copy is $STAGE_UNIT and the staged environment is $STAGE_ENV"

installed=yes
if [[ -f "$UNIT" ]] && ! confirm "A unit already exists at $UNIT — replace it?"; then
  warn "left as it is: nothing written to /etc, and nothing restarted"
  installed=no
  SKIPPED+=("install the systemd unit")
fi

if [[ "$installed" == "yes" ]]; then
  if sudo install -d -m 755 /etc/clodeck \
    && sudo install -m 600 -o root -g root "$STAGE_ENV" /etc/clodeck/clodeck.env; then
    say "wrote /etc/clodeck/clodeck.env ✓ (0600, root-owned)"
  else
    warn "could not write /etc/clodeck/clodeck.env — is sudo still working?"
    SKIPPED+=("the root-owned environment file")
    installed=no
  fi
fi

if [[ "$installed" == "yes" ]]; then
  if sudo install -m 644 "$STAGE_UNIT" "$UNIT"; then
    say "wrote $UNIT ✓"
    sudo systemctl daemon-reload
    # `restart`, not `enable --now`: on a re-run the unit is already running, and
    # a start-if-stopped would leave the old environment in place — the values
    # just written to /etc/clodeck/clodeck.env only reach the process on a
    # restart. `restart` starts a stopped unit too, so it covers both cases.
    if sudo systemctl enable clodeck && sudo systemctl restart clodeck; then
      say "clodeck is enabled and restarted ✓"
    else
      warn "systemctl could not start it — read: sudo journalctl -u clodeck -n 50"
      SKIPPED+=("start the service")
    fi
  else
    warn "could not write $UNIT"
    SKIPPED+=("the systemd unit")
  fi
fi

pause

# ── 8. The firewall ───────────────────────────────────────────────────────
stage "The firewall"
say "The port has to be reachable before any browser can be."
note ""

if [[ "$(_existing HOST || true)" == "0.0.0.0" ]]; then
  if command -v ufw >/dev/null 2>&1; then
    if sudo ufw status 2>/dev/null | grep -qi '^Status: active'; then
      if sudo ufw allow "$PORT/tcp"; then
        say "ufw allows $PORT/tcp ✓"
      else
        warn "ufw refused the rule"
        SKIPPED+=("open $PORT/tcp in ufw")
      fi
    else
      note "ufw is installed but inactive, so there is no rule to add. This wizard"
      note "does not enable it: enabling a firewall over SSH without an allow for"
      note "your own SSH port is how a session is lost."
    fi
  elif command -v firewall-cmd >/dev/null 2>&1; then
    if sudo firewall-cmd --permanent --add-port="$PORT/tcp" && sudo firewall-cmd --reload; then
      say "firewalld allows $PORT/tcp ✓"
    else
      warn "firewalld refused the rule"
      SKIPPED+=("open $PORT/tcp in firewalld")
    fi
  else
    note "neither ufw nor firewalld is here, so there is no local firewall to open."
  fi

  note ""
  warn "a rented server usually has a second firewall in the provider's web panel"
  warn "(security group / firewall rules / cloud firewall). $PORT/tcp has to be"
  warn "open there too, and no command on this host can do it for you. The symptom"
  warn "of forgetting is a browser that hangs until it times out."
else
  note "the app binds loopback, so no port is exposed and there is nothing to open."
  note "Only the tunnel in stage 7 reaches it."
fi

pause

# ── 9. First light ────────────────────────────────────────────────────────
stage "First light"
say "Waiting for the server to answer /healthz…"

answered=no
for _ in $(seq 1 15); do
  if curl -fsS --max-time 3 "http://127.0.0.1:$PORT/healthz" 2>/dev/null | grep -q '"status":"ok"'; then
    answered=yes
    break
  fi
  sleep 1
done

if [[ "$answered" == "yes" ]]; then
  say "it answers {\"status\":\"ok\"} ✓"
else
  warn "no answer on 127.0.0.1:$PORT yet. Read the server's own first lines:"
  note "    sudo journalctl -u clodeck -n 50"
  note "each warning there names its own fix — a missing password, no projects"
  note "root, a port already taken."
  SKIPPED+=("check that the server came up (http://127.0.0.1:$PORT/healthz)")
fi

note ""
if [[ -n "${CLODECK_PUBLIC_URL:-}" ]]; then
  say "Open it at:"
  note "    $CLODECK_PUBLIC_URL"
else
  say "Tunnel in from your own machine, then open:"
  note "    http://localhost:$PORT"
fi

say ""
say "Sign in with the password from stage 3. Then, in order:"
step "Pick a project on the left, or use New project to make one."
step "The picker above the composer reads 'running on <model> · <profile>'. Choose."
step "Send a turn. The picker locks after it — a different provider means New chat in the header."
step "The rail's Terminal and Files open one drawer below the chat, for the selected project."
note ""
note "A project whose .claude/settings.json declares its own ANTHROPIC_BASE_URL or"
note "ANTHROPIC_AUTH_TOKEN is pinned: the picker offers tiers only, and the run"
note "carries the model while the project keeps the endpoint and the credential."

note ""
say "From here on, on this machine:"
note "    sudo systemctl restart clodeck      # after any change to /etc/clodeck/clodeck.env"
note "    sudo journalctl -u clodeck -f       # the server's log"
note "    git pull && npm ci && npm run build && sudo systemctl restart clodeck"
note "A restart drops every session: session ids live in the server's memory."
note "Re-running this wizard is how you change a value: it offers what is already"
note "saved, and stage 7 reinstalls and restarts."
# ──────────────────────────────────────────────────────────────────────────

finish
